:5px}.dash-error p{font-size:13px;color:#888}.dash-error button{font-size:13px;color:#ff0a30;padding:8px 0}@keyframes grow{from{transform:scaleY(.1)}to{transform:scaleY(1)}}@media(prefers-reduced-motion:reduce){.mini-track i{animation:none}}@media(max-width:350px){.dash-card{padding:17px 15px}.week-number{font-size:36px}.mini-chart{gap:5px}.week-main{gap:10px}.dash-entries>a{padding:16px 10px;gap:6px}.entry-icon{width:27px}.dash-entries div>span{font-size:8px}.pb-grid b{font-size:15px}.career-numbers b{font-size:25px}}
